// tenant extraction and signature check (pseudo)
const tenantId = req.headers['x-tenant-id'];
const secret = await getSecretFromKeyVault(tenantId);
const valid = verifyHMAC(req.body, secret, req.headers['x-signature']);
if (!valid) return { status: 401 };
await cosmos.upsert({ tenantId, eventId: req.headers['x-event-id'], ...payload });
